-- Auditable Event Intelligence Agent Platform V2
-- PostgreSQL 15+ baseline schema. UUIDs are generated by the application so
-- this migration does not require a privileged database extension.

CREATE TABLE projects (
    id UUID PRIMARY KEY,
    name VARCHAR(200) NOT NULL,
    description TEXT,
    created_by VARCHAR(200) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE model_versions (
    id UUID PRIMARY KEY,
    component_kind VARCHAR(32) NOT NULL CHECK (
        component_kind IN ('model', 'prompt', 'toolset', 'policy')
    ),
    name VARCHAR(200) NOT NULL,
    version VARCHAR(200) NOT NULL,
    provider VARCHAR(100),
    artifact_uri TEXT,
    config JSONB NOT NULL DEFAULT '{}'::jsonb,
    config_sha256 CHAR(64) NOT NULL CHECK (config_sha256 ~ '^[0-9a-f]{64}$'),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (component_kind, name, version, config_sha256)
);

CREATE TABLE analysis_jobs (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id),
    requested_by VARCHAR(200) NOT NULL,
    idempotency_key VARCHAR(200) NOT NULL,
    status VARCHAR(32) NOT NULL CHECK (status IN (
        'queued', 'running', 'retrying', 'degraded', 'manual_required',
        'failed_closed', 'completed'
    )),
    event_id VARCHAR(200) NOT NULL,
    query TEXT NOT NULL,
    request_payload JSONB NOT NULL,
    result_payload JSONB,
    error_code VARCHAR(100),
    error_message TEXT,
    attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    started_at TIMESTAMPTZ,
    finished_at TIMESTAMPTZ,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (project_id, idempotency_key)
);

CREATE INDEX idx_analysis_jobs_project_status
    ON analysis_jobs(project_id, status, created_at DESC);

CREATE TABLE comments (
    id UUID PRIMARY KEY,
    job_id UUID NOT NULL REFERENCES analysis_jobs(id) ON DELETE CASCADE,
    sample_id VARCHAR(200) NOT NULL,
    text TEXT NOT NULL,
    context TEXT,
    source_url TEXT,
    input_sha256 CHAR(64) NOT NULL CHECK (input_sha256 ~ '^[0-9a-f]{64}$'),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (job_id, sample_id)
);

CREATE TABLE agent_runs (
    id UUID PRIMARY KEY,
    job_id UUID NOT NULL REFERENCES analysis_jobs(id) ON DELETE CASCADE,
    trace_id VARCHAR(64) NOT NULL UNIQUE,
    attempt INTEGER NOT NULL CHECK (attempt >= 1),
    status VARCHAR(32) NOT NULL CHECK (status IN (
        'running', 'retrying', 'degraded', 'manual_required',
        'failed_closed', 'completed'
    )),
    model_version_id UUID NOT NULL REFERENCES model_versions(id),
    prompt_version_id UUID NOT NULL REFERENCES model_versions(id),
    toolset_version_id UUID NOT NULL REFERENCES model_versions(id),
    policy_version_id UUID NOT NULL REFERENCES model_versions(id),
    version_snapshot JSONB NOT NULL,
    input_state JSONB NOT NULL,
    output_state JSONB,
    token_input INTEGER NOT NULL DEFAULT 0 CHECK (token_input >= 0),
    token_output INTEGER NOT NULL DEFAULT 0 CHECK (token_output >= 0),
    started_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    finished_at TIMESTAMPTZ,
    UNIQUE (job_id, attempt)
);

CREATE INDEX idx_agent_runs_job_started
    ON agent_runs(job_id, started_at DESC);

CREATE TABLE retrieved_evidence (
    id UUID PRIMARY KEY,
    run_id UUID NOT NULL REFERENCES agent_runs(id) ON DELETE CASCADE,
    evidence_id VARCHAR(200) NOT NULL,
    event_id VARCHAR(200) NOT NULL,
    rank INTEGER NOT NULL CHECK (rank >= 1),
    retrieval_backend VARCHAR(100) NOT NULL,
    score DOUBLE PRECISION NOT NULL,
    text TEXT NOT NULL,
    source_url TEXT,
    accepted BOOLEAN NOT NULL,
    rejection_reason TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (run_id, evidence_id)
);

CREATE TABLE tool_calls (
    id UUID PRIMARY KEY,
    run_id UUID NOT NULL REFERENCES agent_runs(id) ON DELETE CASCADE,
    sequence_no INTEGER NOT NULL CHECK (sequence_no >= 1),
    node_name VARCHAR(100) NOT NULL,
    tool_name VARCHAR(200) NOT NULL,
    status VARCHAR(32) NOT NULL CHECK (
        status IN ('running', 'succeeded', 'retrying', 'degraded', 'failed_closed')
    ),
    request_payload JSONB NOT NULL,
    response_payload JSONB,
    error_type VARCHAR(100),
    duration_ms DOUBLE PRECISION CHECK (duration_ms >= 0),
    token_input INTEGER NOT NULL DEFAULT 0 CHECK (token_input >= 0),
    token_output INTEGER NOT NULL DEFAULT 0 CHECK (token_output >= 0),
    started_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    finished_at TIMESTAMPTZ,
    UNIQUE (run_id, sequence_no)
);

CREATE TABLE human_reviews (
    id UUID PRIMARY KEY,
    job_id UUID NOT NULL REFERENCES analysis_jobs(id) ON DELETE CASCADE,
    run_id UUID NOT NULL REFERENCES agent_runs(id) ON DELETE CASCADE,
    comment_id UUID REFERENCES comments(id) ON DELETE CASCADE,
    reviewer_id VARCHAR(200) NOT NULL,
    idempotency_key VARCHAR(200) NOT NULL,
    previous_label VARCHAR(32),
    final_label VARCHAR(32) NOT NULL CHECK (
        final_label IN ('Positive', 'Neutral', 'Negative', 'Unscorable')
    ),
    rationale TEXT,
    submitted_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (job_id, idempotency_key)
);

COMMENT ON COLUMN analysis_jobs.request_payload IS
    'Immutable normalized request used for deterministic replay.';
COMMENT ON COLUMN agent_runs.version_snapshot IS
    'Model, prompt, toolset and policy identity captured at run start.';
